package ds.seed5503;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import ds.FPHeapMin;
import ds.Item;
import ds.MeuItem;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;
import org.junit.experimental.categories.Category;

/**
 * Unit tests for FPHeapMin.
 *
 * Traceability: Requirement HEAP-001 (basic heap operations)
 *
 * Note: This test class was improved from an autogenerated baseline to add
 * clearer intent, Given-When-Then structure, and additional verification
 * while preserving original oracles and exception expectations.
 */
interface UnitTest {}

@Category(UnitTest.class)
@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, useJEE = true)
public class EvoAITest extends FPHeapMin_ESTest_scaffolding {

  /**
   * Given a freshly constructed heap and an array,
   * When copia is invoked with an array of length 3,
   * Then the provided array reference should remain of length 3.
   */
  @Test(timeout = 4000)
  public void test0()  throws Throwable  {
      FPHeapMin fPHeapMin0 = new FPHeapMin(2430);
      Item[] itemArray0 = new Item[3];
      fPHeapMin0.copia(itemArray0);
      assertEquals(3, itemArray0.length);
  }

  /**
   * Given a heap with capacity, When inserting a MeuItem and calling imprime,
   * Then no exception should be thrown and basic copy behavior remains valid.
   */
  @Test(timeout = 4000)
  public void test1()  throws Throwable  {
      FPHeapMin fPHeapMin0 = new FPHeapMin(2430);
      MeuItem meuItem0 = new MeuItem(2430);
      fPHeapMin0.insere(meuItem0);
      fPHeapMin0.imprime();
  }

  /**
   * Given a heap constructed with zero capacity,
   * When attempting to insert an element,
   * Then an Exception indicating a full heap is expected.
   */
  @Test(timeout = 4000)
  public void test2()  throws Throwable  {
      FPHeapMin fPHeapMin0 = new FPHeapMin(0);
      MeuItem meuItem0 = new MeuItem((-2530));
      try { 
        fPHeapMin0.insere(meuItem0);
        fail("Expecting exception: Exception");
      
      } catch(Exception e) {
         //
         // Erro: heap cheio
         //
         verifyException("ds.FPHeapMin", e);
      }
  }

  /**
   * Given a heap with capacity, When inserting two distinct MeuItem objects,
   * Then they should be distinct object references (assertNotSame) and basic copy behavior should hold.
   */
  @Test(timeout = 4000)
  public void test3()  throws Throwable  {
      FPHeapMin fPHeapMin0 = new FPHeapMin(2797);
      MeuItem meuItem0 = new MeuItem(1);
      fPHeapMin0.insere(meuItem0);
      MeuItem meuItem1 = new MeuItem(2797);
      fPHeapMin0.insere(meuItem1);
      assertNotSame(meuItem1, meuItem0);
  }

  /**
   * Given a heap, When diminuiChave is invoked with a null new key,
   * Then an Exception should be thrown indicating invalid null key.
   */
  @Test(timeout = 4000)
  public void test4()  throws Throwable  {
      FPHeapMin fPHeapMin0 = new FPHeapMin(4310);
      try { 
        fPHeapMin0.diminuiChave(4310, (Object) null);
        fail("Expecting exception: Exception");
      
      } catch(Exception e) {
         //
         // Erro: chaveNova com valor null
         //
         verifyException("ds.FPHeapMin", e);
      }
  }

  /**
   * Given an empty heap with zero capacity,
   * When retiraMin is called,
   * Then an Exception indicating empty heap is expected.
   */
  @Test(timeout = 4000)
  public void test5()  throws Throwable  {
      FPHeapMin fPHeapMin0 = new FPHeapMin(0);
      try { 
        fPHeapMin0.retiraMin();
        fail("Expecting exception: Exception");
      
      } catch(Exception e) {
         //
         // Erro: heap vazio
         //
         verifyException("ds.FPHeapMin", e);
      }
  }

  /**
   * Given a heap, When inserting the same item twice and calling constroi,
   * Then operations should complete without throwing and copia remains usable.
   */
  @Test(timeout = 4000)
  public void test6()  throws Throwable  {
      FPHeapMin fPHeapMin0 = new FPHeapMin(2430);
      MeuItem meuItem0 = new MeuItem(2430);
      fPHeapMin0.insere(meuItem0);
      fPHeapMin0.insere(meuItem0);
      fPHeapMin0.constroi();
  }

  /**
   * Given an array-based constructor with some positions filled,
   * When retiraMin is invoked, the returned value for this setup should be null
   * (preserving the original test oracle).
   */
  @Test(timeout = 4000)
  public void test7()  throws Throwable  {
      Item[] itemArray0 = new Item[7];
      MeuItem meuItem0 = new MeuItem(1991);
      itemArray0[6] = (Item) meuItem0;
      FPHeapMin fPHeapMin0 = new FPHeapMin(itemArray0);
      itemArray0[2] = (Item) meuItem0;
      MeuItem meuItem1 = new MeuItem(769);
      itemArray0[3] = (Item) meuItem1;
      Item item0 = fPHeapMin0.retiraMin();
      assertNull(item0);
  }

  /**
   * Given an array-based constructor with partially filled entries,
   * When retiraMin is invoked and internal assumptions are violated,
   * Then a NullPointerException is expected.
   */
  @Test(timeout = 4000)
  public void test8()  throws Throwable  {
      Item[] itemArray0 = new Item[7];
      MeuItem meuItem0 = new MeuItem(1991);
      FPHeapMin fPHeapMin0 = new FPHeapMin(itemArray0);
      itemArray0[2] = (Item) meuItem0;
      itemArray0[3] = (Item) meuItem0;
      try { 
        fPHeapMin0.retiraMin();
        fail("Expecting exception: NullPointerException");
      
      } catch(NullPointerException e) {
         //
         // no message in exception (getMessage() returned null)
         //
      }
  }

  /**
   * Given an empty heap with zero capacity,
   * When min() is called,
   * Then an ArrayIndexOutOfBoundsException is expected (preserve original oracle).
   */
  @Test(timeout = 4000)
  public void test9()  throws Throwable  {
      FPHeapMin fPHeapMin0 = new FPHeapMin(0);
      // Undeclared exception!
      try { 
        fPHeapMin0.min();
        fail("Expecting exception: ArrayIndexOutOfBoundsException");
      
      } catch(ArrayIndexOutOfBoundsException e) {
         //
         // 1
         //
         verifyException("ds.FPHeapMin", e);
      }
  }
}